insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MZ', 'default', 'PGC-NIRF — Plano Geral de Contabilidade para as Normas Internacionais de Relato Financeiro (selecção)', '{}'::jsonb, true, 'companies', array['MZ-NIRF-BAL', 'MZ-NIRF-DR']::text[], null, 'Decreto n.º 70/2009, de 22 de Dezembro, que aprova o Sistema de Contabilidade para o Sector Empresarial (SCE). O SCE comporta o PGC-NIRF, aplicável às médias entidades, o PGC-PE, aplicável às pequenas entidades, e as Normas Internacionais de Relato Financeiro completas, aplicáveis às grandes entidades e às entidades cotadas. O capítulo 1.5 fixa o código de contas em oito classes (1 Meios financeiros, 2 Inventários e activos biológicos, 3 Investimentos de capital, 4 Contas a receber, contas a pagar, acréscimos e diferimentos, 5 Capital próprio, 6 Gastos e perdas, 7 Rendimentos e ganhos, 8 Resultados). Esta selecção retoma os códigos e as denominações do quadro detalhado, com os pontos dos níveis suprimidos (4.4.3.3.1 escreve-se 44331), e acrescenta apenas as subcontas 44324 (IVA dedutível nas importações), 4691 (alfândegas, IVA de importação a pagar), 4699 (conta transitória a regularizar) e 68991 (diferenças de arredondamento), cuja denominação assinala o facto. A lista completa é a do decreto.', 'decreto-70-2009')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

