insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MZ', 'MZ-P-16-EXC', 'Compra à taxa normal (16 %) com dedução excluída (art. 20, n.º 1)', '{}'::jsonb, 'Viaturas de turismo, combustíveis, transportes e viagens, alojamento, alimentação, representação, telefone móvel, divertimento e luxo', 'percent', 16, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 20, n.º 1 — exclui-se do direito à dedução o imposto contido nas despesas de (a) aquisição, locação e reparação de viaturas de turismo, barcos de recreio, helicópteros, aviões, motos e motociclos, (c) transportes e viagens do sujeito passivo e do seu pessoal, (d) alojamento, alimentação, bebidas e tabaco e recepção, (e) comunicações telefónicas, excepto telefone fixo em nome do sujeito passivo, e (f) divertimento e luxo; o n.º 3 afasta a exclusão da alínea a) para quem tem a venda ou a exploração desses bens como actividade. O imposto não recuperável integra o custo.', null, null, 160, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-16-FA', 'Compra de activos tangíveis e intangíveis à taxa normal (16 %), dedutível', '{}'::jsonb, 'Equipamento, mobiliário e outros activos fixos', 'percent', 16, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 18, n.º 1, alínea a) — o sujeito passivo deduz o imposto que lhe foi facturado na aquisição de bens e serviços por outros sujeitos passivos; n.º 2 — só confere direito à dedução o imposto mencionado em facturas ou documentos equivalentes emitidos por sujeitos passivos inscritos no IVA (redacção da Lei n.º 10/2025); art. 19, n.º 1 — o imposto só se deduz se os bens e serviços forem usados em operações tributadas ou isentas com direito à dedução. Modelo A, quadro 5, campo 05 (imobilizado).', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-16-FUEL', 'Compra de gasóleo à taxa normal (16 %), dedutível a 50 %', '{}'::jsonb, 'Gasóleo para viaturas que não estão excluídas por categoria: o imposto é dedutível na proporção de 50 %', 'percent', 16, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 20, n.º 1, alínea b) — exclui-se do direito à dedução o imposto das despesas com combustíveis normalmente utilizáveis em viaturas automóveis, com excepção do gasóleo, cujo imposto é dedutível na proporção de 50 %, a menos que se trate de veículos pesados de passageiros, veículos licenciados para transporte público de passageiros (excepto rent a car), máquinas consumidoras de gasóleo não matriculadas ou tractores agrícolas, caso em que é integralmente dedutível (use MZ-P-16-SVC). Metade vai ao campo 07 do Modelo A e a outra metade fica no custo da compra.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-16-INV', 'Compra de inventários à taxa normal (16 %), dedutível', '{}'::jsonb, 'Mercadorias, matérias-primas e materiais adquiridos a um sujeito passivo para operações com direito à dedução', 'percent', 16, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 18, n.º 1, alínea a) — o sujeito passivo deduz o imposto que lhe foi facturado na aquisição de bens e serviços por outros sujeitos passivos; n.º 2 — só confere direito à dedução o imposto mencionado em facturas ou documentos equivalentes emitidos por sujeitos passivos inscritos no IVA (redacção da Lei n.º 10/2025); art. 19, n.º 1 — o imposto só se deduz se os bens e serviços forem usados em operações tributadas ou isentas com direito à dedução. Modelo A, quadro 5, campo 06 (existências).', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-16-ND5', 'Compra à taxa normal (16 %) afecta a operações à taxa reduzida de 5 %, dedução excluída', '{}'::jsonb, 'O imposto de bens e serviços usados para operações sujeitas à taxa reduzida do art. 17-A não é dedutível desde 1 de Janeiro de 2026', 'percent', 16, 'purchase', 'domestic', date '2026-01-01', null, 'Código do IVA, art. 19, n.º 2, na redacção da Lei n.º 10/2025 (em vigor desde 1 de Janeiro de 2026) — não há direito à dedução do imposto respeitante às transmissões de bens e prestações de serviços previstas no art. 17-A, isto é, às que são tributadas à taxa de 5 %. O imposto de uma compra usada exclusivamente nessas operações integra o custo; o imposto de uma compra de uso misto exigiria uma repartição que o pacote não calcula (ver o README).', null, null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-16-SVC', 'Compra de outros bens e serviços à taxa normal (16 %), dedutível', '{}'::jsonb, 'Serviços e fornecimentos correntes', 'percent', 16, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 18, n.º 1, alínea a) — o sujeito passivo deduz o imposto que lhe foi facturado na aquisição de bens e serviços por outros sujeitos passivos; n.º 2 — só confere direito à dedução o imposto mencionado em facturas ou documentos equivalentes emitidos por sujeitos passivos inscritos no IVA (redacção da Lei n.º 10/2025); art. 19, n.º 1 — o imposto só se deduz se os bens e serviços forem usados em operações tributadas ou isentas com direito à dedução. Modelo A, quadro 5, campo 07 (outros bens e serviços).', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-17', 'Compra à taxa normal de 17 % (até 31/12/2022), dedutível', '{}'::jsonb, 'Código fechado: a taxa normal antes da Lei n.º 22/2022', 'percent', 17, 'purchase', 'domestic', date '2008-01-01', date '2022-12-31', 'Código do IVA, art. 18, n.º 1, alínea a) — o sujeito passivo deduz o imposto que lhe foi facturado na aquisição de bens e serviços por outros sujeitos passivos; n.º 2 — só confere direito à dedução o imposto mencionado em facturas ou documentos equivalentes emitidos por sujeitos passivos inscritos no IVA (redacção da Lei n.º 10/2025); art. 19, n.º 1 — o imposto só se deduz se os bens e serviços forem usados em operações tributadas ou isentas com direito à dedução. A taxa de 17 % foi substituída por 16 % em 1 de Janeiro de 2023 (Lei n.º 22/2022, art. 6). Modelo A, campo 07.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-5-ND', 'Compra à taxa reduzida (5 %), dedução excluída', '{}'::jsonb, 'Serviço de saúde, ensino ou formação profissional adquirido a taxa de 5 %: o imposto pago não é dedutível', 'percent', 5, 'purchase', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 20, n.º 2, aditado pela Lei n.º 22/2022 — exclui-se do direito à dedução o imposto pago nas transmissões de bens e prestações de serviços sujeitas à taxa reduzida do art. 17-A; art. 19, n.º 2 (redacção da Lei n.º 10/2025) — idem. O imposto integra o custo da compra.', null, null, 180, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-EX', 'Compra isenta', '{}'::jsonb, 'Prémio de seguro ou outra compra isenta, sem imposto a deduzir', 'percent', 0, 'purchase', 'exempt', date '2008-01-01', null, 'Código do IVA, art. 9 — as transmissões de bens e prestações de serviços isentas não levam imposto; nada há a deduzir e a compra não chega a nenhum campo do Modelo A.', null, null, 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-IMP', 'Importação de bens à taxa normal (16 %), imposto pago na alfândega', '{}'::jsonb, 'IVA liquidado no desembaraço aduaneiro, dedutível pelo importador', 'percent', 16, 'purchase', 'import', date '2023-01-01', null, 'Código do IVA, art. 5 (a importação de bens está sujeita a imposto), art. 7, n.º 1, alínea c) (o imposto é devido no desembaraço aduaneiro) e art. 18, n.º 1, alínea b) — o sujeito passivo deduz o imposto devido pela importação de bens, mencionado no bilhete de despacho (n.º 2). Modelo A, campo 08. O imposto debitado a 44324 tem como contrapartida a conta 4691, saldada com o pagamento à alfândega.', null, null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-P-RC-16', 'Serviço ou bem digital adquirido a um não residente (autoliquidação, 16 %)', '{}'::jsonb, 'Serviços do art. 6, n.º 7 (consultoria, publicidade, direitos, locação, bens e serviços digitais) prestados por quem não tem sede, estabelecimento estável nem domicílio em Moçambique', 'percent', 16, 'purchase', 'foreign_services_received', date '2023-01-01', null, 'Código do IVA, art. 6, n.º 7 — são tributáveis, quando o prestador não tem sede, estabelecimento estável ou domicílio em território nacional, as cessões de direitos, a publicidade, as telecomunicações, os serviços de consultores, a locação de bens móveis e, desde a Lei n.º 10/2025 (alínea k), os bens e serviços digitais (sítios, programas, bases de dados, música, filmes e jogos, ensino à distância, SaaS, computação em nuvem); art. 26, n.os 3 e 4 — o adquirente cumpre as obrigações do prestador não residente; art. 18, n.º 1, alíneas c) e d) — o imposto pago como destinatário é dedutível; art. 32, n.º 1, alínea c) — o prazo da declaração das operações do art. 26, n.º 4 é o dia 10 do mês seguinte. O Modelo A não tem campo para a autoliquidação: o pacote lança a base e o imposto liquidado nos campos 01 e 02, e o imposto dedutível no campo 07 (hipótese a rever, ver o README).', null, null, 210, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-16', 'Venda ou prestação de serviços à taxa normal (16 %)', '{}'::jsonb, 'Transmissão de bens ou prestação de serviços tributada que não é isenta nem sujeita à taxa reduzida', 'percent', 16, 'sale', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 17, n.º 1, na redacção da Lei n.º 22/2022, de 28 de Dezembro (art. 1; em vigor desde 1 de Janeiro de 2023, art. 6): a taxa do imposto é de 16 %; n.º 2 — aplica-se a taxa em vigor no momento em que o imposto se torna exigível. Modelo A, quadro 5, campos 01 (base) e 02 (imposto liquidado). `vat_category` e `exemption_code` ficam nulos: o pacote não declara perfil de factura electrónica.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-17', 'Venda ou prestação de serviços à taxa normal de 17 % (até 31/12/2022)', '{}'::jsonb, 'Código fechado: a taxa normal antes da Lei n.º 22/2022', 'percent', 17, 'sale', 'domestic', date '2008-01-01', date '2022-12-31', 'Código do IVA, art. 17, n.º 1, na redacção anterior à Lei n.º 22/2022, de 28 de Dezembro: a taxa do imposto era de 17 %; a nova redacção, de 16 %, está em vigor desde 1 de Janeiro de 2023 (art. 6 da Lei n.º 22/2022). A data de início, 1 de Janeiro de 2008, é a da entrada em vigor do Código aprovado pela Lei n.º 32/2007 e não está no texto consolidado consultado: ver o README.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-5', 'Venda ou prestação de serviços à taxa reduzida (5 %)', '{}'::jsonb, 'Serviços médicos e sanitários de estabelecimentos privados, ensino e formação profissional privados, lições a título pessoal', 'percent', 5, 'sale', 'domestic', date '2023-01-01', null, 'Código do IVA, art. 17-A, aditado pela Lei n.º 22/2022 (em vigor desde 1 de Janeiro de 2023): taxa reduzida de 5 % para (a) os serviços médicos e sanitários prestados por estabelecimentos hospitalares privados, clínicas, dispensários e similares, (b) o ensino ministrado por estabelecimentos privados integrados no Sistema Nacional de Ensino, (c) a formação profissional prestada por entidades privadas e (d) as lições dadas a título pessoal. O Modelo A não tem campo próprio para a taxa reduzida: a base e o imposto vão nos campos 01 e 02, e o Portal do Contribuinte informa que os sujeitos passivos à taxa de 5 % entregam, enquanto o portal não é adaptado, uma guia nas unidades de cobrança e pedem o documento de arrecadação (GARE).', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-EX', 'Venda ou prestação de serviços isenta sem direito à dedução (saúde e ensino públicos e outras)', '{}'::jsonb, 'Serviços médicos de estabelecimentos hospitalares públicos, ensino de estabelecimentos públicos, locação de imóveis para habitação, entre outras isenções do art. 9', 'percent', 0, 'sale', 'exempt', date '2023-01-01', null, 'Código do IVA, art. 9, n.º 1, alínea a) (serviços médicos e sanitários de estabelecimentos hospitalares públicos), n.º 3 (ensino e formação profissional por estabelecimentos e entidades públicos), n.º 5 (locação de imóveis para fins de habitação) e restantes isenções das operações internas que o art. 19, n.º 1 não faz seguir de direito à dedução. A Lei n.º 22/2022 retirou os estabelecimentos privados destas isenções, hoje sujeitos à taxa de 5 % (art. 17-A). Modelo A, campo 04.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-EX-FIN', 'Operação bancária, financeira ou de seguro, isenta sem direito à dedução', '{}'::jsonb, 'Operações sujeitas a imposto do selo (art. 9, n.os 4 e 6)', 'percent', 0, 'sale', 'exempt', date '2023-01-01', null, 'Código do IVA, art. 9, n.º 4 — estão isentas as operações bancárias e financeiras sujeitas ao imposto do selo — e n.º 6 — as operações de seguro e resseguro e os serviços conexos de corretores e mediadores sujeitas a imposto do selo (n.os 4 e 6 na redacção da Lei n.º 22/2022). Sem direito à dedução: art. 19, n.º 1 não inclui estas isenções. Modelo A, campo 04.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-EX-STAPLES', 'Venda de bens de primeira necessidade, isenta com direito à dedução', '{}'::jsonb, 'Milho, farinha de milho, arroz, pão, sal iodado, trigo, tomate, batata, cebola, carapau congelado, gás doméstico, entre outros (art. 9, n.º 10)', 'percent', 0, 'sale', 'exempt', date '2008-01-01', null, 'Código do IVA, art. 9, n.º 10 — estão isentas as transmissões de milho, farinha de milho, arroz, pão, sal iodado, leite em pó para lactente até um ano, trigo, farinha de trigo, tomate fresco ou refrigerado, batata, cebola, carapau congelado, petróleo de iluminação, gás doméstico (GPL), jet fuel, bicicletas comuns, preservativos e insecticidas; art. 19, n.º 1, alínea b), subalínea v) — estas isenções, tal como as do n.º 7, alínea a), do n.º 12, alínea f) e do n.º 13, alíneas d) e f) do art. 9, conferem direito à dedução. Por isso a base vai no campo 03 do Modelo A e não no 04.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-EXP', 'Exportação de bens, isenta com direito à dedução', '{}'::jsonb, 'Bens expedidos ou transportados para o estrangeiro pelo vendedor, pelo adquirente não residente ou por um terceiro por conta destes', 'percent', 0, 'sale', 'export', date '2008-01-01', null, 'Código do IVA, art. 13, n.º 1, alíneas a) e b) — estão isentas as transmissões de bens expedidos ou transportados com destino ao estrangeiro pelo vendedor ou por conta deste, ou por um adquirente sem residência nem estabelecimento em território nacional; art. 19, n.º 1, alínea b), subalínea i) — as exportações e operações isentas nos termos do art. 13 conferem direito à dedução (o equivalente de uma taxa zero); art. 25, n.º 5 — a isenção é comprovada por documentos aduaneiros apropriados. Modelo A, campo 03.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('MZ', 'MZ-S-EXP-SVC', 'Transporte internacional de pessoas e serviços assimilados a exportações, isentos com direito à dedução', '{}'::jsonb, 'Transporte de pessoas provenientes ou com destino ao estrangeiro, serviços ligados à expedição de bens para o estrangeiro, trabalhos sobre bens móveis reexpedidos', 'percent', 0, 'sale', 'export', date '2008-01-01', null, 'Código do IVA, art. 13, n.º 1, alíneas n) (serviços relacionados com a expedição de bens destinados ao estrangeiro), p) (o transporte de pessoas provenientes ou com destino ao estrangeiro) e q) (trabalhos sobre bens móveis reexpedidos para o estrangeiro); art. 19, n.º 1, alínea b), subalínea i) — direito à dedução. Modelo A, campo 03.', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
