insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MZ', 'MZ-IVA-MODELO-A', 'Declaração Periódica de IVA — Modelo A (regime normal)', array['month']::declaration_period[], 'month'::declaration_period, date '2008-01-01', null, 'Código do IVA, art. 25, n.º 1, alínea c), e art. 32, n.º 1 — os sujeitos passivos entregam mensalmente a declaração periódica, mesmo sem operações tributáveis (art. 25, n.º 2); o Modelo A (art. 36 do Código em vigor à data do formulário) é entregue pelo e-Declaração, obrigatório desde Junho de 2022, e no Portal do Contribuinte. Os campos 01 a 15 abaixo são os do formulário oficial lido em 9 de Outubro de 2026. Ficam fora do pacote o quadro 1 de identificação, o quadro 4 (inexistência de operações), a utilização de créditos de períodos anteriores (campos 16 e 17), o quadro 6 (imposto a entregar, juros de mora, campos 18 a 20) e o quadro 7 (reporte e pedido de reembolso, campos 21 a 23): ver o README. O regime simplificado e o regime de isenção foram revogados pela Lei n.º 10/2025 (art. 3), pelo que todos os sujeitos passivos entregam o Modelo A.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Código do IVA, art. 32, n.º 1, na redacção da Lei n.º 10/2025 — a declaração periódica entrega-se (b) até ao último dia do mês seguinte àquele a que respeitam as operações, quando há imposto a pagar; (a) até ao décimo quinto dia do mês seguinte, quando a declaração apresenta créditos ou não tem operações; (c) até ao décimo dia do mês seguinte, para as operações do art. 26, n.º 4 (bens e serviços digitais adquiridos a não residentes). O pacote tem uma única data por declaração e retém o último dia do mês seguinte, o prazo da declaração com imposto a pagar; os prazos do dia 15 e do dia 10 estão no README.', 'civa', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

