values
  ('MZ', 'MZ-IVA-MODELO-A', '01', 'base', 'Transmissões de bens e prestações de serviços tributadas — base tributável', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 01 — base tributável das transmissões de bens e prestações de serviços efectuadas pelo sujeito passivo (o formulário refere ainda a taxa de 17 % do texto anterior a 2023).', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '02', 'tax', 'Imposto liquidado', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 02 — imposto liquidado sobre as operações do campo 01.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '03', 'base', 'Operações isentas com direito à dedução (exportações e assimiladas)', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 03 — operações isentas referidas no art. 19, n.º 1, alínea b) (o formulário cita a alínea b) do n.º 1 do art. 18, numeração anterior ao texto actual).', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '04', 'base', 'Operações que não conferem direito à dedução', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 04 — operações isentas que não conferem direito à dedução.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '05', 'tax', 'Imposto dedutível — imobilizado', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 2, campo 05 — imposto dedutível respeitante às aquisições de imobilizado.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '06', 'tax', 'Imposto dedutível — existências', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 2, campo 06 — imposto dedutível respeitante às aquisições de existências.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '07', 'tax', 'Imposto dedutível — outros bens e serviços', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 2, campo 07 — imposto dedutível respeitante a outros bens e serviços.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '08', 'tax', 'Imposto dedutível — importações', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 3, campo 08 — imposto dedutível suportado nas importações de bens.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '09', 'tax', 'Regularizações a favor do sujeito passivo', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 4, campo 09 — regularizações mensais ou anuais, excepto as comunicadas pela Administração Fiscal. Nenhuma taxa do pacote escreve neste campo: preenche-se à mão.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '10', 'tax', 'Regularizações a favor do Estado', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, n.º 4, campo 10 — regularizações mensais ou anuais a favor do Estado. Nenhuma taxa do pacote escreve neste campo: preenche-se à mão.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '11', 'total', 'Valor da liquidação', '{}'::jsonb, 110, null, array['01', '03', '04']::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 11 — soma dos campos 01, 03 e 04.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '12', 'total', 'Total do imposto dedutível', '{}'::jsonb, 120, null, array['05', '06', '07', '08', '09']::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 12 — soma dos campos 05, 06, 07, 08 e 09.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '13', 'total', 'Total do imposto liquidado', '{}'::jsonb, 130, null, array['02', '10']::text[], '{}'::text[], null, null, false, false, null, 'Modelo A, quadro 5, campo 13 — soma dos campos 02 e 10.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '14', 'total', 'Imposto a favor do Estado', '{}'::jsonb, 140, null, array['13']::text[], array['12']::text[], null, null, true, false, null, 'Modelo A, quadro 5, campo 14 — se o campo 13 é superior ao campo 12, a diferença (13 − 12); alimenta o quadro 6, imposto a entregar ao Estado.', 'modelo-a'),
  ('MZ', 'MZ-IVA-MODELO-A', '15', 'total', 'Imposto a favor do sujeito passivo', '{}'::jsonb, 150, null, array['12']::text[], array['13']::text[], null, null, true, false, null, 'Modelo A, quadro 5, campo 15 — se o campo 12 é superior ao campo 13, a diferença (12 − 13); alimenta o quadro 7, imposto a recuperar (reporte para o período seguinte ou pedido de reembolso).', 'modelo-a')
on conflict (country, report_code, box, kind) do update set
