insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('MZ-NIRF-BAL', 'MZ', 'default', 'Balanço', 'balance_sheet', 'MZ-PGC-NIRF', date '2010-01-01', null, 'Decreto n.º 70/2009, de 22 de Dezembro, capítulo 1.6 — modelo de Balanço do SCE: activos não correntes e correntes; capital próprio e passivos não correntes e correntes. As denominações são as do modelo oficial (colunas Notas, Período n e Período n-1 não representadas); o mapeamento conta a conta é uma selecção feita para este pacote, a partir dos códigos do capítulo 1.5. Não se representam os activos biológicos não correntes, os outros passivos financeiros nem os interesses minoritários, para os quais o plano não tem conta nesta selecção. A linha do resultado líquido junta aos saldos da classe 8 o resultado ainda não apurado das contas das classes 6 e 7, de modo que o balanço fecha antes e depois do apuramento.', 'decreto-70-2009'),
  ('MZ-NIRF-DR', 'MZ', 'default', 'Demonstração dos resultados por naturezas', 'income_statement', 'MZ-PGC-NIRF', date '2010-01-01', null, 'Decreto n.º 70/2009, de 22 de Dezembro, capítulo 1.6 — modelo da Demonstração dos resultados por naturezas do SCE. As denominações são as do modelo oficial (colunas Notas, Período n e Período n-1 não representadas); o mapeamento conta a conta é uma selecção feita para este pacote. Não se representam os ganhos e perdas imputados de associadas, o resultado das operações descontinuadas, a repartição por detentores nem os resultados por acção. A linha 12 reúne as classes 67, 68, 74, 75, 76 e 79.', 'decreto-70-2009')
