update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Código do IVA, art. 27, n.º 5 — as facturas ou documentos equivalentes são emitidos em língua e moeda nacionais, datados, numerados sequencialmente e contêm, entre outros elementos, o NUIT do fornecedor e do adquirente, o preço líquido de imposto, a taxa e o montante do imposto, o motivo da não aplicação do imposto e o Número de Identificação Bancária (NIB) para o qual é efectuado o pagamento; o n.º 4 exige pelo menos duplicado. A lei pede uma numeração sequencial e não proíbe expressamente uma falha, pelo que o estilo declarado é `sequential`.',
  numbering_source_key          = 'civa',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Código do IVA, art. 7 — o imposto é devido e exigível, nas transmissões de bens, quando os bens são postos à disposição do adquirente e, nas prestações de serviços, quando são realizadas ou, se antes, quando o preço é cobrado; art. 8 — havendo obrigação de emitir factura, o imposto torna-se exigível no momento da emissão, ou no termo do prazo de emissão se este não for respeitado, ou ainda no momento de um pagamento, mesmo parcial, anterior à factura. A regra geral é a entrega ou a realização, e a factura emitida substitui-a: é o sentido de `invoice_if_issued`, ao qual o vocabulário fechado não acrescenta o pagamento antecipado do art. 8, alínea c).',
  tax_point_source_key          = 'civa',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Nenhum diploma moçambicano impõe às empresas a troca entre si de uma factura electrónica estruturada (não existe autoridade Peppol, perfil publicado nem esquema ISO 6523 de endereçamento), pelo que `profile`, `party_scheme` e `vat_scheme` ficam nulos e `obligation` é `none`. O que Moçambique tem é outro mecanismo, de comunicação ao Estado e não de troca entre partes: o Código do IVA, art. 27, n.º 10 (aditado em 2016) obriga a comunicar as facturas à Autoridade Tributária, e o Aviso n.º 40/AT/DGI/2025, de 27 de Março, pôs a obrigação em prática: a partir de Maio de 2025, os sujeitos passivos que emitem facturas por programa informático comunicam todos os meses, pelo e-Declaração, o ficheiro (XML, XLSX ou CSV) das facturas do mês anterior, extraído de um programa de facturação certificado pela Autoridade Tributária (Despacho Ministerial de 29 de Fevereiro de 2012); a comunicação do ficheiro SAF-T (Moz) completo, o regulamento de certificação de software e o regime das máquinas fiscais ligadas à Autoridade Tributária estavam anunciados ou em implementação gradual à data de redacção, sem facturação em tempo real em vigor. O socle não representa este mecanismo; a lacuna está escrita no README do pacote e em docs/international.md.',
  einvoice_source_key           = 'aviso-40-2025',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
